 1→@use 'sass:map';
 2→@use '@angular/material' as mat;
 3→@use 'styles' ;
 4→
 5→@include mat.elevation-classes();
 6→@include mat.app-background();
 7→
 8→$my-typography: mat.m2-define-typography-config();
 9→@include mat.typography-hierarchy($my-typography);
10→
11→// Note: Color palettes are generated from primary: #ffffff
12→$_palettes: (
13→  primary: mat.$blue-palette,
14→  tertiary: mat.$red-palette,
15→);
16→
17→$_primary: map.get($_palettes, primary);
18→
19→$light-theme: mat.define-theme((
20→  color: (
21→    theme-type: light,
22→    primary: $_primary,
23→  ),
24→));
25→
26→$dark-theme: mat.define-theme((
27→  color: (
28→    theme-type: dark,
29→    primary: $_primary,
30→  ),
31→));
32→
33→html {
34→  @include mat.all-component-themes($light-theme);
35→
36→  .dark-theme {
37→    @include mat.all-component-colors($dark-theme);
38→  }
39→}

