const body = getComputedStyle(document.body);
const h1 = document.querySelector('h1');
const h1Styles = h1 ? getComputedStyle(h1) : null;
const nav = document.querySelector('nav, header');
const navStyles = nav ? getComputedStyle(nav) : null;

JSON.stringify({
  bodyFont: body.fontFamily,
  bodyColor: body.color,
  bodyBg: body.backgroundColor,
  h1Font: h1Styles?.fontFamily,
  h1Size: h1Styles?.fontSize,
  h1Weight: h1Styles?.fontWeight,
  h1LetterSpacing: h1Styles?.letterSpacing,
  h1LineHeight: h1Styles?.lineHeight,
  h1Color: h1Styles?.color,
  navBg: navStyles?.backgroundColor,
  // Get all custom properties
  allFonts: Array.from(document.styleSheets).flatMap(sheet => {
    try {
      return Array.from(sheet.cssRules).filter(r => r.selectorText === ':root').flatMap(r => r.cssText.match(/--[^:]+:\s*[^;]+/g) || []).filter(v => v.includes('font') || v.includes('color') || v.includes('bg'));
    } catch(e) { return []; }
  }).slice(0, 30),
}, null, 2);

// Get more design details
const styles = getComputedStyle(document.documentElement);

// Get feature card styles
const cards = document.querySelectorAll('[class*="card"], [class*="feature"]');
const firstCard = cards[0];
const cardStyles = firstCard ? getComputedStyle(firstCard) : null;

// Get the italic text in h1
const h1 = document.querySelector('h1');
const h1Italic = h1?.querySelector('em, i, [style*="italic"]');
const italicStyles = h1Italic ? getComputedStyle(h1Italic) : null;

// Get button styles
const buttons = document.querySelectorAll('a[class*="btn"], button[class*="btn"], a[class*="download"], [class*="cta"]');
const btn = buttons[0] || document.querySelector('a[href*="download"]');
const btnStyles = btn ? getComputedStyle(btn) : null;

// Get all font-face declarations
const fontFaces = Array.from(document.styleSheets).flatMap(sheet => {
  try {
    return Array.from(sheet.cssRules)
      .filter(r => r instanceof CSSFontFaceRule)
      .map(r => r.style.fontFamily);
  } catch(e) { return []; }
});

JSON.stringify({
  cardBg: cardStyles?.backgroundColor,
  cardBorder: cardStyles?.border,
  cardBorderRadius: cardStyles?.borderRadius,
  italicFont: italicStyles?.fontFamily,
  italicStyle: italicStyles?.fontStyle,
  btnBg: btnStyles?.backgroundColor,
  btnBorder: btnStyles?.border,
  btnBorderRadius: btnStyles?.borderRadius,
  btnFont: btnStyles?.fontFamily,
  btnPadding: btnStyles?.padding,
  fontFaces: [...new Set(fontFaces)],
  // CSS variables for colors
  teal: styles.getPropertyValue('--clr-core-pop-10'),
  gray100: styles.getPropertyValue('--clr-core-gray-100'),
  gray90: styles.getPropertyValue('--clr-core-gray-90'),
  gray80: styles.getPropertyValue('--clr-core-gray-80'),
}, null, 2);

