import BaseLayout from './BaseLayout.astro';

interface Props {
  title: string;
  description: string;
  pubDate: Date;
  updatedDate?: Date;
  author: string;
  tags?: string[];
}

const { title, description, pubDate, updatedDate, author, tags = [] } = Astro.props;

const formattedDate = pubDate.toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});

const formattedUpdatedDate = updatedDate?.toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
---

<BaseLayout title={`${title} | IPTVnator Blog`} description={description}>
  <article class="pt-32 pb-20">
    <div class="mx-auto max-w-3xl px-6">
      <!-- Back link -->
      <a
        href="/iptvnator/blog/"
        class="inline-flex items-center gap-1 text-sm text-slate-500 transition-colors hover:text-white"
      >
        <svg class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7" />
        </svg>
        Back to blog
      </a>

      <!-- Header -->
      <header class="mt-8">
        <div class="flex flex-wrap items-center gap-2">
          <time datetime={pubDate.toISOString()} class="text-sm text-slate-500">
            {formattedDate}
          </time>
          {
            tags.length > 0 && (
              <>
                <span class="text-slate-700">&middot;</span>
                {tags.map((tag) => (
                  <span class="rounded-full bg-brand-500/10 px-2.5 py-0.5 text-xs font-medium text-brand-400">
                    {tag}
                  </span>
                ))}
              </>
            )
          }
        </div>

        <h1 class="mt-4 text-3xl font-bold tracking-tight text-white sm:text-4xl">
          {title}
        </h1>

        <p class="mt-4 text-lg text-slate-400">{description}</p>

        <div class="mt-6 flex items-center gap-3">
          <div class="flex h-8 w-8 items-center justify-center rounded-full bg-brand-500/20 text-sm font-bold text-brand-400">
            {author.charAt(0).toUpperCase()}
          </div>
          <div>
            <div class="text-sm font-medium text-white">{author}</div>
            {
              updatedDate && (
                <div class="text-xs text-slate-500">
                  Updated {formattedUpdatedDate}
                </div>
              )
            }
          </div>
        </div>
      </header>

      <!-- Content -->
      <div
        class="prose prose-invert prose-slate mt-12 max-w-none prose-headings:font-semibold prose-headings:tracking-tight prose-a:text-brand-400 prose-a:no-underline hover:prose-a:underline prose-code:rounded prose-code:bg-white/5 prose-code:px-1.5 prose-code:py-0.5 prose-code:text-brand-300 prose-code:before:content-[''] prose-code:after:content-[''] prose-pre:border prose-pre:border-white/5 prose-pre:bg-white/[0.02]"
      >
        <slot />
      </div>
    </div>
  </article>
</BaseLayout>

---
import { getCollection } from 'astro:content';
import BaseLayout from '../layouts/BaseLayout.astro';
import Hero from '../components/Hero.astro';
import FeatureGrid from '../components/FeatureGrid.astro';
import ScreenshotShowcase from '../components/ScreenshotShowcase.astro';
import DownloadCTA from '../components/DownloadCTA.astro';
import BlogPostCard from '../components/BlogPostCard.astro';

const posts = (await getCollection('blog'))
  .filter((post) => !post.data.draft)
  .sort((a, b) => b.data.pubDate.valueOf() - a.data.pubDate.valueOf())
  .slice(0, 3);
---

<BaseLayout
  title="IPTVnator - Open Source IPTV Player"
  description="A cross-platform IPTV player supporting M3U/M3U8 playlists, Xtream Codes API, and Stalker portals. Available as a desktop app and PWA."
>
  <Hero />
  <FeatureGrid />
  <ScreenshotShowcase />
  <DownloadCTA />

  <!-- Recent Blog Posts -->
  {
    posts.length > 0 && (
      <section class="py-24">
        <div class="mx-auto max-w-7xl px-6">
          <div class="flex items-end justify-between">
            <div>
              <h2 class="text-3xl font-bold tracking-tight text-white sm:text-4xl">
                Latest from the blog
              </h2>
              <p class="mt-4 text-lg text-slate-400">
                Release notes, tutorials, and project updates.
              </p>
            </div>
            <a
              href="/iptvnator/blog/"
              class="hidden items-center gap-1 text-sm text-brand-400 hover:text-brand-300 sm:inline-flex"
            >
              View all posts
              <svg class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 8l4 4m0 0l-4 4m4-4H3" />
              </svg>
            </a>
          </div>

          <div class="mt-10 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {posts.map((post) => (
              <BlogPostCard
                title={post.data.title}
                description={post.data.description}
                pubDate={post.data.pubDate}
                slug={post.id}
                tags={post.data.tags}
              />
            ))}
          </div>
        </div>
      </section>
    )
