@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply scroll-smooth;
  }

  body {
    @apply bg-surface-950 text-surface-200 antialiased font-body;
    background-image:
      radial-gradient(ellipse 80% 50% at 50% -20%, rgba(32, 168, 168, 0.08), transparent),
      url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
  }

  ::selection {
    @apply bg-accent-500/30 text-white;
  }

  ::-webkit-scrollbar {
    @apply w-1.5;
  }

  ::-webkit-scrollbar-track {
    @apply bg-transparent;
  }

  ::-webkit-scrollbar-thumb {
    @apply rounded-full bg-surface-600 hover:bg-surface-500;
  }
}

@layer components {
  /* Section divider - dotted line like GitButler */
  .section-divider {
    border: none;
    border-top: 1px dashed theme('colors.surface.700');
    @apply mx-auto max-w-5xl;
  }

  /* Stagger animation delays for children */
  .stagger-children > * {
    @apply opacity-0 animate-fade-up;
  }
  .stagger-children > *:nth-child(1) { animation-delay: 0ms; }
  .stagger-children > *:nth-child(2) { animation-delay: 80ms; }
  .stagger-children > *:nth-child(3) { animation-delay: 160ms; }
  .stagger-children > *:nth-child(4) { animation-delay: 240ms; }
  .stagger-children > *:nth-child(5) { animation-delay: 320ms; }
  .stagger-children > *:nth-child(6) { animation-delay: 400ms; }
  .stagger-children > *:nth-child(7) { animation-delay: 480ms; }
  .stagger-children > *:nth-child(8) { animation-delay: 560ms; }
  .stagger-children > *:nth-child(9) { animation-delay: 640ms; }
  .stagger-children > *:nth-child(10) { animation-delay: 720ms; }
  .stagger-children > *:nth-child(11) { animation-delay: 800ms; }
  .stagger-children > *:nth-child(12) { animation-delay: 880ms; }

  /* Card with dotted border */
  .card-dotted {
    @apply border border-dashed border-surface-600/60 rounded-lg p-6;
    @apply transition-all duration-300;
  }
  .card-dotted:hover {
    @apply border-accent-500/40 bg-accent-500/[0.03];
  }

  /* Glow effect for images */
  .glow-frame {
    position: relative;
  }
  .glow-frame::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    background: linear-gradient(135deg, rgba(32, 168, 168, 0.3), transparent 40%, transparent 60%, rgba(32, 168, 168, 0.15));
    z-index: -1;
    filter: blur(1px);
  }
}

