file.content:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply scroll-smooth;
  }

  body {
    @apply bg-surface-950 text-surface-200 antialiased font-body;
    background-image:
      radial-gradient(ellipse 80% 50% at 50% -20%, rgba(32, 168, 168, 0.07), transparent),
      url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.025'/%3E%3C/svg%3E");
  }

  ::selection {
    @apply bg-accent-500/30 text-white;
  }

  ::-webkit-scrollbar {
    @apply w-1.5;
  }

  ::-webkit-scrollbar-track {
    @apply bg-transparent;
  }

  ::-webkit-scrollbar-thumb {
    @apply rounded-full bg-surface-600 hover:bg-surface-500;
  }
}

@layer components {
  .section-divider {
    border: none;
    border-top: 1px dashed theme('colors.surface.700');
    @apply mx-auto max-w-5xl;
  }

  .stagger-children > * {
    @apply opacity-0 animate-fade-up;
  }
  .stagger-children > *:nth-child(1) { animation-delay: 0ms; }
  .stagger-children > *:nth-child(2) { animation-delay: 80ms; }
  .stagger-children > *:nth-child(3) { animation-delay: 160ms; }
  .stagger-children > *:nth-child(4) { animation-delay: 240ms; }
  .stagger-children > *:nth-child(5) { animation-delay: 320ms; }
  .stagger-children > *:nth-child(6) { animation-delay: 400ms; }
  .stagger-children > *:nth-child(7) { animation-delay: 480ms; }
  .stagger-children > *:nth-child(8) { animation-delay: 560ms; }
  .stagger-children > *:nth-child(9) { animation-delay: 640ms; }
  .stagger-children > *:nth-child(10) { animation-delay: 720ms; }
  .stagger-children > *:nth-child(11) { animation-delay: 800ms; }
  .stagger-children > *:nth-child(12) { animation-delay: 880ms; }

  .card-dotted {
    @apply border border-dashed border-surface-600/60 rounded-lg p-6 transition-all duration-300;
  }
  .card-dotted:hover {
    @apply border-accent-500/40 bg-accent-500/[0.03];
  }
}

/** @type {import('tailwindcss').Config} */
export default {
  content: ['./src/**/*.{astro,html,js,jsx,md,mdx,ts,tsx}'],
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        surface: {
          950: '#0a0a08',
          900: '#121210',
          850: '#1a1a17',
          800: '#22221e',
          700: '#2e2e28',
          600: '#3a3a33',
          500: '#52524a',
          400: '#6b6b62',
          300: '#8a8a80',
          200: '#b0b0a6',
          100: '#d4d4cc',
          50: '#f0f0eb',
        },
        accent: {
          950: '#021c1c',
          900: '#053838',
          800: '#0a5454',
          700: '#107070',
          600: '#178c8c',
          500: '#20a8a8',
          400: '#38c4c4',
          300: '#5ee0e0',
          200: '#8aecec',
          100: '#b8f4f4',
          50: '#e0fafa',
        },
        warm: {
          500: '#d4a853',
          400: '#e0bc6a',
          300: '#ecd08a',
        },
      },
      fontFamily: {
        display: ['"Playfair Display"', 'Georgia', 'serif'],
        body: ['"DM Sans"', 'system-ui', 'sans-serif'],
        mono: ['"IBM Plex Mono"', 'monospace'],
      },
      fontSize: {
        '7xl': ['4.5rem', { lineHeight: '1.05', letterSpacing: '-0.03em' }],
        '8xl': ['6rem', { lineHeight: '1', letterSpacing: '-0.04em' }],
        '9xl': ['8rem', { lineHeight: '0.95', letterSpacing: '-0.04em' }],
      },
      animation: {
        'fade-up': 'fadeUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards',
        'fade-in': 'fadeIn 0.6s ease forwards',
        'glow-pulse': 'glowPulse 4s ease-in-out infinite',
        'scan': 'scan 8s linear infinite',
      },
      keyframes: {
        fadeUp: {
          '0%': { opacity: '0', transform: 'translateY(30px)' },
          '100%': { opacity: '1', transform: 'translateY(0)' },
        },
        fadeIn: {
          '0%': { opacity: '0' },
          '100%': { opacity: '1' },
        },
        glowPulse: {
          '0%, 100%': { opacity: '0.4' },
          '50%': { opacity: '0.8' },
        },
        scan: {
          '0%': { transform: 'translateY(-100%)' },
          '100%': { transform: 'translateY(100%)' },
        },
      },
    },
  },
  plugins: [],
};

