                <div class="absolute -inset-6 rounded-2xl bg-accent-500/[0.03] blur-2xl" />

                <!-- Window chrome -->
                <div class="relative overflow-hidden rounded-xl border border-surface-700/60 bg-surface-900 shadow-2xl shadow-black/30">
