<section id="screenshots" class="relative py-24">
  <div class="mx-auto max-w-7xl px-6">
    <div class="mx-auto max-w-2xl text-center">
      <h2 class="text-3xl font-bold tracking-tight text-white sm:text-4xl">
        See it in action
      </h2>
      <p class="mt-4 text-lg text-slate-400">
        A clean, intuitive interface designed for the best viewing experience.
      </p>
    </div>

    <div class="mt-12">
      <!-- Tabs -->
      <div class="flex flex-wrap justify-center gap-2" role="tablist">
        {
          tabs.map((tab, i) => (
            <button
              role="tab"
              aria-selected={i === 0 ? 'true' : 'false'}
              data-tab={tab.id}
              class:list={[
                'screenshot-tab rounded-lg px-4 py-2 text-sm font-medium transition-all',
                i === 0
                  ? 'bg-brand-600 text-white'
                  : 'text-slate-400 hover:bg-white/5 hover:text-white',
              ]}
            >
              {tab.label}
            </button>
          ))
        }
      </div>

      <!-- Screenshots -->
      <div class="relative mt-8">
        {
          tabs.map((tab, i) => (
            <div
              data-panel={tab.id}
              class:list={[
                'screenshot-panel',
                i !== 0 && 'hidden',
              ]}
            >
              <div class="relative mx-auto max-w-4xl">
                <div class="absolute -inset-2 rounded-2xl bg-gradient-to-r from-brand-500/10 to-purple-500/10 blur-lg" />
                <div class="relative overflow-hidden rounded-xl border border-white/10 shadow-2xl">
                  <Image
                    src={tab.image}
                    alt={tab.alt}
                    width={1000}
                    class="w-full"
                  />
                </div>
              </div>
            </div>
          ))
        }
      </div>
    </div>
  </div>
</section>

<script>
  const tabs = document.querySelectorAll('.screenshot-tab');
  const panels = document.querySelectorAll('.screenshot-panel');

  tabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      const target = (tab as HTMLElement).dataset.tab;

      tabs.forEach((t) => {
        t.classList.remove('bg-brand-600', 'text-white');
        t.classList.add('text-slate-400');
        t.setAttribute('aria-selected', 'false');
      });
      tab.classList.add('bg-brand-600', 'text-white');
      tab.classList.remove('text-slate-400');
      tab.setAttribute('aria-selected', 'true');

      panels.forEach((panel) => {
        if ((panel as HTMLElement).dataset.panel === target) {
          panel.classList.remove('hidden');
        } else {
          panel.classList.add('hidden');
        }
      });
    });
  });
</script>

