// Analyze the blog grid layout
const articles = document.querySelectorAll('article');
const container = articles[0]?.parentElement;
const containerStyles = container ? window.getComputedStyle(container) : null;

const result = {
  containerTag: container?.tagName,
  containerClasses: container?.className?.substring(0, 200),
  display: containerStyles?.display,
  gridTemplateColumns: containerStyles?.gridTemplateColumns,
  gridTemplateRows: containerStyles?.gridTemplateRows,
  gap: containerStyles?.gap,
  articleCount: articles.length,
  articles: Array.from(articles).slice(0, 6).map((a, i) => {
    const style = window.getComputedStyle(a);
    const img = a.querySelector('img');
    return {
      index: i,
      gridColumn: style.gridColumn,
      gridRow: style.gridRow,
      hasImage: !!img,
      imageAspect: img ? `${img.naturalWidth}x${img.naturalHeight}` : null,
      titleText: a.querySelector('h2, h3')?.textContent?.trim()?.substring(0, 50),
    };
  })
};
JSON.stringify(result, null, 2);

// Analyze different row types on the blog page
const allRows = document.querySelectorAll('[class*="Row"], [class*="row"]');
const rowInfo = Array.from(allRows).slice(0, 10).map(row => {
  const style = window.getComputedStyle(row);
  const articles = row.querySelectorAll('article');
  return {
    className: row.className.substring(0, 100),
    display: style.display,
    gridTemplateColumns: style.gridTemplateColumns,
    gap: style.gap,
    articleCount: articles.length,
    children: row.children.length,
  };
});

// Also check the main container for the whole blog layout
const main = document.querySelector('main');
const mainStyle = main ? window.getComputedStyle(main) : null;

JSON.stringify({
  mainDisplay: mainStyle?.display,
  mainGap: mainStyle?.gap,
  rows: rowInfo,
}, null, 2);

// Analyze blog layout sections - check class names as strings safely
const main = document.querySelector('main');
const sections = main ? Array.from(main.children) : [];

const layout = sections.slice(0, 12).map((section, i) => {
  const style = window.getComputedStyle(section);
  const cls = typeof section.className === 'string' ? section.className : section.className?.baseVal || '';
  const articles = section.querySelectorAll('article');
  const imgs = section.querySelectorAll('img');
  return {
    index: i,
    tag: section.tagName,
    class: cls.substring(0, 120),
    display: style.display,
    gridCols: style.gridTemplateColumns?.substring(0, 80),
    gap: style.gap,
    articleCount: articles.length,
    imgCount: imgs.length,
  };
});

JSON.stringify(layout, null, 2);

// Go deeper into the flex container to see the row-level layout
const wrap = document.querySelector('.content-wrap');
const children = wrap ? Array.from(wrap.children) : [];

const rows = children.slice(0, 10).map((child, i) => {
  const style = window.getComputedStyle(child);
  const cls = typeof child.className === 'string' ? child.className : '';
  const articles = child.querySelectorAll('article');
  return {
    index: i,
    tag: child.tagName,
    classShort: cls.replace(/[A-Za-z]+_[a-z]+__\w+/g, m => m.split('_')[0]).substring(0, 100),
    display: style.display,
    gridCols: style.gridTemplateColumns !== 'none' ? style.gridTemplateColumns.substring(0, 80) : null,
    gap: style.gap !== 'normal' ? style.gap : null,
    articleCount: articles.length,
    width: style.width?.substring(0, 20),
  };
});

JSON.stringify(rows, null, 2);

