  .btn-tv:hover::before {
    opacity: 1;
  }

  .btn-tv:hover .tv-scanline {
    opacity: 1;
  }

  .btn-tv:hover .tv-noise {
    opacity: 0.04;
    animation: tvFlicker 0.15s infinite;
  }

  .btn-tv:hover .tv-vignette {
    opacity: 1;
  }

