      text-shadow:
        0 0 rgba(32, 168, 168, 0),
        0 0 rgba(255, 100, 100, 0);
    }
    94% {
      text-shadow:
        2px 0 rgba(32, 168, 168, 0.4),
        -2px 0 rgba(255, 100, 100, 0.2);
    }
    95% {
      text-shadow:
        -1px 0 rgba(32, 168, 168, 0.3),
        1px 0 rgba(255, 100, 100, 0.15);
    }
    96% {
      text-shadow:
        3px 0 rgba(32, 168, 168, 0.5),
        -3px 0 rgba(255, 100, 100, 0.25);
    }
    97% {
      text-shadow:
        0 0 rgba(32, 168, 168, 0),
        0 0 rgba(255, 100, 100, 0);
    }
  }
}

